#!/usr/bin/env python3
import pathlib, subprocess, os
ROOT=pathlib.Path("/home/apr/eth-hedge-live")
BOT=ROOT/"manual_live_helper.py"
BOT.write_text("#!/usr/bin/env python3\nfrom __future__ import annotations\nimport json, os, pathlib, time, urllib.parse, urllib.request\nfrom datetime import datetime, timezone\n\nROOT=pathlib.Path(\"/home/apr/eth-hedge-live\")\nMONITOR_STATE=ROOT/\"state.json\"\nMONITOR_CONFIG=ROOT/\"config.json\"\nOUT=ROOT/\"manual_status.json\"\nLEDGER=ROOT/\"manual_status_ledger.jsonl\"\n\nACCOUNT=749122\nMARKET_INDEX=0\nMAX_QTY=0.1\nTP_PCT=0.003\nADVERSE_PCT=0.015\nFRESH_SEC=90\n\ndef now_ms(): return int(time.time()*1000)\ndef iso(ms=None):\n    if ms is None: return datetime.now(timezone.utc).isoformat()\n    return datetime.fromtimestamp(ms/1000,tz=timezone.utc).isoformat()\n\ndef loadj(p,default=None):\n    if not p.exists(): return default\n    return json.loads(p.read_text())\n\ndef savej(p,obj):\n    t=p.with_suffix(p.suffix+\".tmp\")\n    t.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+\"\\n\",encoding=\"utf-8\")\n    os.replace(t,p)\n    os.chmod(p,0o600)\n\ndef emit(event,**kw):\n    row={\"event\":event,\"at\":iso(),**kw}\n    with LEDGER.open(\"a\",encoding=\"utf-8\") as f:\n        f.write(json.dumps(row,ensure_ascii=False,separators=(\",\",\":\"))+\"\\n\")\n\ndef account():\n    url=\"https://mainnet.zklighter.elliot.ai/api/v1/account?\"+urllib.parse.urlencode({\n        \"by\":\"index\",\"value\":str(ACCOUNT),\"active_only\":\"false\"\n    })\n    req=urllib.request.Request(url,headers={\"User-Agent\":\"eth-manual-live-helper/1.0\"})\n    with urllib.request.urlopen(req,timeout=15) as r:\n        j=json.load(r)\n    a=(j.get(\"accounts\") or [{}])[0]\n    positions=[]\n    for p in a.get(\"positions\") or []:\n        try:q=abs(float(p.get(\"position\") or 0))\n        except Exception:q=0.0\n        if q<=1e-12: continue\n        raw_mid=p.get(\"market_id\")\n        if raw_mid is None: raw_mid=p.get(\"market_index\",-1)\n        positions.append({\n            \"market_id\":int(raw_mid),\n            \"symbol\":p.get(\"symbol\"),\n            \"sign\":int(p.get(\"sign\") or 0),\n            \"qty\":q,\n            \"avg_entry_price\":float(p.get(\"avg_entry_price\") or 0),\n            \"liquidation_price\":float(p.get(\"liquidation_price\") or 0),\n            \"unrealized_pnl\":float(p.get(\"unrealized_pnl\") or 0),\n        })\n    return {\n        \"available_balance\":float(a.get(\"available_balance\") or 0),\n        \"collateral\":float(a.get(\"collateral\") or 0),\n        \"positions\":positions,\n    }\n\ndef main():\n    cfg=loadj(MONITOR_CONFIG,{}) or {}\n    mon=loadj(MONITOR_STATE,{}) or {}\n    acct=account()\n    if int(cfg.get(\"account_index\") or 0)!=749122 or int(cfg.get(\"api_key_index\") or -1)!=45:\n        raise RuntimeError(\"monitor identity mismatch\")\n    if cfg.get(\"mode\")!=\"LOCKED_NO_ORDERS\":\n        raise RuntimeError(\"monitor execution mode changed unexpectedly\")\n\n    eth=None\n    other=[]\n    for p in acct[\"positions\"]:\n        if p[\"market_id\"]==MARKET_INDEX:\n            eth=p\n        else:\n            other.append(p)\n\n    out={\n        \"updated_at\":iso(),\n        \"account_index\":749122,\n        \"execution\":\"MANUAL_ONLY\",\n        \"max_short_eth\":0.1,\n        \"spot_actions\":\"MANUAL_ONLY\",\n        \"auto_stop_loss\":False,\n        \"auto_timeout_exit\":False,\n        \"tp_pct\":TP_PCT,\n        \"adverse_diag_pct\":ADVERSE_PCT,\n        \"account\":{\n            \"available_balance\":acct[\"available_balance\"],\n            \"collateral\":acct[\"collateral\"],\n            \"positions\":acct[\"positions\"],\n        }\n    }\n\n    if other:\n        out[\"status\"]=\"BLOCKED_OTHER_POSITION\"\n        out[\"action\"]=\"DO_NOT_ENTER\"\n        out[\"reason\"]=\"non-ETH position exists in dedicated account\"\n    elif eth:\n        if eth[\"sign\"]!=-1:\n            out[\"status\"]=\"BLOCKED_WRONG_SIDE\"\n            out[\"action\"]=\"DO_NOT_ENTER\"\n            out[\"reason\"]=\"ETH position is not a short\"\n        elif eth[\"qty\"]>0.10005:\n            out[\"status\"]=\"BLOCKED_SIZE_OVER_CAP\"\n            out[\"action\"]=\"DO_NOT_ADD\"\n            out[\"reason\"]=\"short size exceeds 0.1 ETH cap\"\n        else:\n            entry=float(eth[\"avg_entry_price\"])\n            out[\"status\"]=\"MANUAL_SHORT_OPEN\"\n            out[\"action\"]=\"HOLD_OR_MANAGE_MANUALLY\"\n            out[\"position\"]={\n                **eth,\n                \"suggested_tp_price\":entry*(1-TP_PCT),\n                \"adverse_1_5_price\":entry*(1+ADVERSE_PCT),\n                \"note\":\"+1.5% and 60m are diagnostics only; no forced exit\"\n            }\n    else:\n        sig=mon.get(\"active_signal\")\n        if not isinstance(sig,dict):\n            out[\"status\"]=\"WAITING_SIGNAL\"\n            out[\"action\"]=\"NONE\"\n        else:\n            sig_ts=int(sig.get(\"signal_close_ts\") or 0)\n            lag=(now_ms()-sig_ts)/1000.0 if sig_ts>0 else 999999\n            if sig_ts<=0 or lag<0 or lag>FRESH_SEC:\n                out[\"status\"]=\"WAITING_SIGNAL\"\n                out[\"action\"]=\"NONE\"\n                out[\"last_signal\"]={\n                    \"signal_close_ts\":sig_ts,\n                    \"signal_close_time\":iso(sig_ts) if sig_ts>0 else None,\n                    \"age_seconds\":round(lag,1) if sig_ts>0 else None,\n                    \"stale\":True\n                }\n            else:\n                entry_ref=float(sig.get(\"entry_reference\") or 0)\n                out[\"status\"]=\"MANUAL_ENTRY_READY\"\n                out[\"action\"]=\"SHORT_0.1_ETH_MANUALLY\"\n                out[\"signal\"]={\n                    \"signal_close_ts\":sig_ts,\n                    \"signal_close_time\":iso(sig_ts),\n                    \"age_seconds\":round(lag,1),\n                    \"rise\":float(sig.get(\"rise\") or 0),\n                    \"buy_share\":float(sig.get(\"buy_share\") or 0),\n                    \"entry_reference\":entry_ref,\n                    \"tp_reference\":entry_ref*(1-TP_PCT),\n                    \"adverse_1_5_reference\":entry_ref*(1+ADVERSE_PCT),\n                    \"size_eth\":0.1,\n                    \"note\":\"Enter manually on Lighter only if you still want this trade; no averaging.\"\n                }\n    savej(OUT,out)\n    print(json.dumps(out,ensure_ascii=False))\n\nif __name__==\"__main__\":\n    main()\n",encoding="utf-8")
os.chmod(BOT,0o700)
subprocess.run(["python3","-m","py_compile",str(BOT)],check=True)
subprocess.run(["python3",str(BOT)],cwd=str(ROOT),check=True,timeout=30)
cron="* * * * * cd /home/apr/eth-hedge-live && python3 /home/apr/eth-hedge-live/manual_live_helper.py >> /home/apr/eth-hedge-live/manual_live_helper.log 2>&1"
r=subprocess.run(["crontab","-l"],text=True,capture_output=True)
lines=r.stdout.splitlines() if r.returncode==0 else []
lines=[x for x in lines if "/home/apr/eth-hedge-live/manual_live_helper.py" not in x]
lines.append(cron)
subprocess.run(["crontab","-"],input="\n".join(lines).rstrip()+"\n",text=True,check=True)
print("ETH_MANUAL_LIVE_HELPER_OK")
print("execution = MANUAL_ONLY")
print("max_short_eth = 0.1")
print("orders_sent = 0")
print("status_file = /home/apr/eth-hedge-live/manual_status.json")
